<?php
declare(strict_types=1);
function sk1050_table(string $t): bool {static $c=[];if(isset($c[$t]))return $c[$t];if(!preg_match('/^[A-Za-z0-9_]+$/',$t))return false;try{$q=db()->prepare('SELECT 1 FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME=?');$q->execute([$t]);return $c[$t]=(bool)$q->fetchColumn();}catch(Throwable $e){return $c[$t]=false;}}
function sk1050_tid(): int {try{if(function_exists('tenant_id'))return (int)tenant_id();if(function_exists('current_tenant')){$t=current_tenant();return (int)($t['id']??0);}}catch(Throwable $e){}return 0;}
function sk1050_uid(): int {try{if(function_exists('current_user')){$u=current_user();return (int)($u['id']??0);}}catch(Throwable $e){}return 0;}
function sk1050_h($v): string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sk1050_settings(?int $tid=null): array {$tid=$tid??sk1050_tid();$d=['enabled'=>1,'merchant_self_service'=>1,'approval_required'=>1,'loyalty_enabled'=>1,'homepage_section_enabled'=>1,'expiry_alerts_enabled'=>1,'points_per_redemption'=>10];if(!sk1050_table('local_deal_settings_v1050'))return $d;try{$q=db()->prepare('SELECT * FROM local_deal_settings_v1050 WHERE tenant_id=?');$q->execute([$tid]);$r=$q->fetch();return $r?array_merge($d,$r):$d;}catch(Throwable $e){return $d;}}
function sk1050_on(string $key='enabled'): bool {$s=sk1050_settings();return (int)($s[$key]??0)===1;}
function sk1050_live_deals(int $limit=12,bool $featured=false): array {if(!sk1050_table('local_deals_v1050'))return [];$tid=sk1050_tid();try{$sql="SELECT d.*,b.name business_name,b.address business_address FROM local_deals_v1050 d LEFT JOIN businesses b ON b.id=d.business_id WHERE d.tenant_id=? AND d.status='active' AND d.starts_at<=NOW() AND d.ends_at>=NOW()".($featured?' AND d.featured=1':'')." ORDER BY d.featured DESC,d.ends_at ASC,d.id DESC LIMIT ".max(1,min(50,$limit));$q=db()->prepare($sql);$q->execute([$tid]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1050_businesses_for_user(int $uid): array {if($uid<1||!sk1050_table('businesses'))return [];try{$cols=[];$q=db()->query("SHOW COLUMNS FROM businesses");foreach($q->fetchAll() as $r)$cols[]=$r['Field'];$owner=in_array('owner_user_id',$cols,true)?'owner_user_id':(in_array('owner_id',$cols,true)?'owner_id':'');if(!$owner)return [];$q=db()->prepare("SELECT id,name FROM businesses WHERE `$owner`=? ORDER BY name");$q->execute([$uid]);return $q->fetchAll()?:[];}catch(Throwable $e){return [];}}
function sk1050_can_manage_deal(array $deal,int $uid): bool {if($uid<1)return false;try{$u=current_user();if($u&&(function_exists('is_super_admin')&&is_super_admin()))return true;if($u&&function_exists('has_permission')&&has_permission('settings.manage',$u))return true;}catch(Throwable $e){}return (int)($deal['owner_user_id']??0)===$uid;}
function sk1050_claim(int $dealId,int $uid): array {if($uid<1)return ['ok'=>false,'message'=>'Please sign in to save this deal.'];$tid=sk1050_tid();try{db()->beginTransaction();$q=db()->prepare("SELECT * FROM local_deals_v1050 WHERE id=? AND tenant_id=? AND status='active' AND starts_at<=NOW() AND ends_at>=NOW() FOR UPDATE");$q->execute([$dealId,$tid]);$d=$q->fetch();if(!$d)throw new RuntimeException('Deal is not available.');if((int)$d['usage_limit']>0&&(int)$d['claimed_count']>=(int)$d['usage_limit'])throw new RuntimeException('This deal has reached its claim limit.');$q=db()->prepare('SELECT COUNT(*) FROM local_deal_claims_v1050 WHERE tenant_id=? AND deal_id=? AND user_id=?');$q->execute([$tid,$dealId,$uid]);if((int)$q->fetchColumn()>=(int)$d['per_user_limit'])throw new RuntimeException('You already saved the maximum allowed claims for this deal.');$code='SK'.strtoupper(substr(bin2hex(random_bytes(7)),0,12));$q=db()->prepare("INSERT INTO local_deal_claims_v1050(tenant_id,deal_id,user_id,claim_code,status,expires_at) VALUES(?,?,?,?,'saved',?)");$q->execute([$tid,$dealId,$uid,$code,$d['ends_at']]);db()->prepare('UPDATE local_deals_v1050 SET claimed_count=claimed_count+1,updated_at=NOW() WHERE id=?')->execute([$dealId]);db()->commit();return ['ok'=>true,'message'=>'Deal saved to your wallet.','code'=>$code];}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();return ['ok'=>false,'message'=>$e->getMessage()];}}
function sk1050_wallet(int $uid): array {if($uid<1)return ['points'=>0,'claims'=>[],'ledger'=>[]];$tid=sk1050_tid();$out=['points'=>0,'claims'=>[],'ledger'=>[]];try{if(sk1050_table('local_loyalty_accounts_v1050')){$q=db()->prepare('SELECT points_balance FROM local_loyalty_accounts_v1050 WHERE tenant_id=? AND user_id=?');$q->execute([$tid,$uid]);$out['points']=(int)($q->fetchColumn()?:0);}if(sk1050_table('local_deal_claims_v1050')){$q=db()->prepare('SELECT c.*,d.title,d.discount_type,d.discount_value,d.minimum_spend,d.ends_at,d.business_id,b.name business_name FROM local_deal_claims_v1050 c JOIN local_deals_v1050 d ON d.id=c.deal_id LEFT JOIN businesses b ON b.id=d.business_id WHERE c.tenant_id=? AND c.user_id=? ORDER BY c.id DESC LIMIT 100');$q->execute([$tid,$uid]);$out['claims']=$q->fetchAll()?:[];}if(sk1050_table('local_loyalty_ledger_v1050')){$q=db()->prepare('SELECT * FROM local_loyalty_ledger_v1050 WHERE tenant_id=? AND user_id=? ORDER BY id DESC LIMIT 30');$q->execute([$tid,$uid]);$out['ledger']=$q->fetchAll()?:[];}}catch(Throwable $e){}return $out;}
function sk1050_redeem(string $code,int $actor): array {$code=strtoupper(trim($code));if($code===''||$actor<1)return ['ok'=>false,'message'=>'Invalid redemption request.'];$tid=sk1050_tid();try{db()->beginTransaction();$q=db()->prepare("SELECT c.*,d.owner_user_id,d.business_id,d.title,d.ends_at FROM local_deal_claims_v1050 c JOIN local_deals_v1050 d ON d.id=c.deal_id WHERE c.tenant_id=? AND c.claim_code=? FOR UPDATE");$q->execute([$tid,$code]);$c=$q->fetch();if(!$c)throw new RuntimeException('Coupon code not found.');if(!sk1050_can_manage_deal($c,$actor))throw new RuntimeException('You are not allowed to redeem this deal.');if($c['status']==='redeemed')throw new RuntimeException('Coupon has already been redeemed.');if(strtotime((string)$c['ends_at'])<time())throw new RuntimeException('Coupon has expired.');$points=(int)(sk1050_settings()['points_per_redemption']??10);db()->prepare("UPDATE local_deal_claims_v1050 SET status='redeemed',reward_points=?,redeemed_at=NOW(),redeemed_by=? WHERE id=?")->execute([$points,$actor,$c['id']]);db()->prepare('UPDATE local_deals_v1050 SET redeemed_count=redeemed_count+1,updated_at=NOW() WHERE id=?')->execute([$c['deal_id']]);if(sk1050_on('loyalty_enabled')&&$points!==0){db()->prepare('INSERT INTO local_loyalty_accounts_v1050(tenant_id,user_id,points_balance,lifetime_points,updated_at) VALUES(?,?,?,?,NOW()) ON DUPLICATE KEY UPDATE points_balance=points_balance+VALUES(points_balance),lifetime_points=lifetime_points+VALUES(lifetime_points),updated_at=NOW()')->execute([$tid,$c['user_id'],$points,max(0,$points)]);db()->prepare("INSERT INTO local_loyalty_ledger_v1050(tenant_id,user_id,event_key,points,reference_type,reference_id,note) VALUES(?,?,'deal_redeemed',?,'deal',?,?)")->execute([$tid,$c['user_id'],$points,$c['deal_id'],'Reward for redeemed deal: '.$c['title']]);}db()->commit();return ['ok'=>true,'message'=>'Coupon redeemed successfully. Customer earned '.$points.' points.'];}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();return ['ok'=>false,'message'=>$e->getMessage()];}}
function sk1050_discount_label(array $d): string {$v=(float)($d['discount_value']??0);$t=(string)($d['discount_type']??'percent');if($t==='amount')return 'PKR '.number_format($v).' OFF';if($t==='fixed_price')return 'PKR '.number_format($v);return rtrim(rtrim(number_format($v,2),0),'.').'% OFF';}
